<script setup lang="ts">
import { Head, Link } from '@inertiajs/vue3';
interface Contract {slug?:string;title:string;subtitle:string|null;object?:string|null;organization?:string|null;status?:string|null;valueCents?:number|null;date?:string|null;supplier?:{name:string;slug:string}|null;procurement?:{number:string|null;slug:string}|null;sourceUrl?:string}
interface RecordData extends Contract {approvedCents?:number|null;contracts?:Contract[]}
const props=defineProps<{kind:'contract'|'procurement'|'supplier';record:RecordData}>(); const money=(v:number)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(v/100); const back=props.kind==='contract'?'contracts.index':props.kind==='procurement'?'procurements.index':'suppliers.index';
</script>
